@startuml

class Customer {
  + VATNumber
  + Name
  + PhoneNumber
  + Address
}

class Package {
  + IdentifierCode
  + Weight
  + Urgency
}

class DeliveryCenter {
  + Name
  + Address
}

class Courier {
  + VATNumber
  + Name
  + PhoneNumber
}

Customer "1" -- "1" DeliveryCenter : is associated to
Customer "1" -- "*" Package : sends
Customer "1" -- "1" Package : receives
Package "*" -- "1" DeliveryCenter : is delivered to
Courier "1" -- "1" DeliveryCenter : works for
Courier "1" -- "0..1" Package : is assigned to

@enduml

